float fbm_hash(float p_v)
{
    float l_f = 43758.5453123f;
    return fract(sin(p_v) * l_f);
}

float fbm_hash(vec2 p_v)
{
    vec2 l_r = vec2(12.9898f, 78.233f);

    //return fbm_hash(sin(p_v.x) * sin(p_v.y) * l_r.x * l_r.y);

    //return fbm_hash(sin(p_v.x * l_r.x) * sin(p_v.y * l_r.y));

    return fbm_hash(dot(p_v, l_r));
}

float basic_noise(vec2 p_v)
{
    vec2 l_int = floor(p_v);
    vec2 l_frac = fract(p_v);
    l_frac = l_frac * l_frac * (3.0f - 2.0f * l_frac);

    float res = mix(mix(fbm_hash(l_int), fbm_hash(l_int + vec2(1.0f, 0.0f)), l_frac.x),
                     mix(fbm_hash(l_int + vec2(0.0f, 1.0f)), fbm_hash(l_int + vec2(1.0f, 1.0f)), l_frac.x),
                     l_frac.y);
    return res * res;
}


float fbm(vec2 p_v, int octaves, float p_amplitude, float p_frequency, float p_lacunarity, float p_gain)
{
    // Rotate to reduce axial bias
    mat2 l_rot_mat = mat2(cos(0.5f), sin(0.5f), -sin(0.5f), cos(0.50f));

    float l_res = 0.0;
    for (int l_i = 0; l_i < octaves; ++l_i) {
        l_res += p_amplitude * basic_noise(p_v * p_frequency);
        p_v = l_rot_mat * p_v;
        p_frequency *= p_lacunarity;
        p_amplitude *= p_gain;
    }
    return l_res;
}

float fbm(vec2 p_v, int p_octaves)
{
    return fbm(p_v, p_octaves, 0.5f, 1.0f, 2.0f, 0.5f);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy - vec2(0.5, 0.5);

    // Time varying pixel color

    vec2 uv_ = uv * vec2(1.0, iResolution.y / iResolution.x) * 100.0;
    //uv_ = fract(uv_);

    vec3 col = vec3(uv_, 0);

    col = vec3(fbm(uv_, 1));

    // Output to screen
    fragColor = vec4(col,1.0);
}
